(function(){'use strict';
const $=id=>document.getElementById(id),D=window.NATIVE_DATA;
if(!D){$('connection-state').textContent='产物元数据未加载，请刷新';return;}
const base='native/fastapi/';let live=false,pending=false;
const views={graph:['graph.html','知识网络 · 原生 graph.html','拖拽与缩放图谱；右侧搜索 APIRouter；点节点查看详情；用 Communities 筛选自动识别的社区。'],tree:['tree.html','层级结构 · 原生树形查看器','点击展开节点；Expand All 展开全部；Collapse All 收拢；Reset View 恢复视角。本次子节点上限高于全图节点数，不触发截断。'],callflow:['callflow.html','调用流程 · 原生中文导出','按上游规则组织社区章节；可缩放流程图并查看调用表。它解释静态关系，不是运行时性能追踪。'],report:['report.html','分析报告 · 上游 Markdown 原文排版','阅读核心实体、跨模块关系、社区与建议问题。正文由上游生成，HTML 仅增加排版；没有替换成我们的总结。'],svg:['graph.svg','原生 SVG · 可缩放矢量图','由 Graphify 原生 SVG 导出器生成，节点与社区完整保留；可独立打开或下载到文档。'],wiki:['wiki/index.html','知识 Wiki · 上游文章目录','按社区和核心实体组织的原生知识文档。HTML 只提供阅读排版；原始 Markdown 保存在同目录。']};
$('scope').textContent=D.scope;$('commit').textContent=D.commit.slice(0,12);
$('metrics').innerHTML=[['files','输入文件'],['nodes','全部节点'],['edges','全部关系'],['communities','自动社区']].map(([key,label])=>`<div><b>${Number(D[key]).toLocaleString()}</b><span>${label}</span></div>`).join('');
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{const v=views[button.dataset.view];$('native-frame').src=base+v[0];$('native-frame').title=v[1];$('open-native').href=base+v[0];$('view-title').textContent=v[1];$('view-help').textContent=v[2];document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
function operation(){const path=$('operation').value==='path';$('second-wrap').hidden=!path;$('second').required=path;$('first-label').textContent=path?'起点':'问题 / 符号';}
function showSaved(command){const record=D.queries.find(q=>q.command===command);if(!record)return;$('operation').value=command;$('first').value=record.arguments[0];$('second').value=record.arguments[1]||'APIRouter';operation();$('query-output').textContent=record.output+(record.stderr?'\n'+record.stderr:'');$('query-caption').textContent='生成时实际运行的上游 CLI 输出 · '+command+' '+record.arguments.join(' → ')+' · 返回码 '+record.exitCode+'。'+(live?'可点击“运行真实查询”重新执行。':'当前显示已保存证据。');}
document.querySelectorAll('[data-query]').forEach(b=>b.addEventListener('click',()=>{if(!pending)showSaved(b.dataset.query);}));
$('operation').addEventListener('change',operation);
$('query-form').addEventListener('submit',async event=>{event.preventDefault();if(!live||pending)return;pending=true;$('run-query').disabled=true;$('run-query').textContent='Graphify 查询中…';$('query-caption').textContent='正在本机调用上游 CLI，结果将原样显示。';try{const command=$('operation').value,args=[$('first').value.trim()];if(command==='path')args.push($('second').value.trim());const response=await fetch('api/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({command,arguments:args}),signal:AbortSignal.timeout(50000)});const result=await response.json();if(!response.ok)throw new Error(result.error||'查询失败');$('query-output').textContent=result.output+(result.stderr?'\n'+result.stderr:'');$('query-caption').textContent='刚刚由 Graphify CLI 执行 · '+command+' · 返回码 '+result.exitCode+' · '+new Date().toLocaleTimeString();}catch(error){$('query-output').textContent=error.message;$('query-caption').textContent='本次查询未成功；没有替换为预设答案。';}finally{pending=false;$('run-query').disabled=!live;$('run-query').textContent='运行真实查询 →';}});
showSaved('explain');$('run-query').disabled=true;
fetch('api/status').then(r=>r.ok?r.json():Promise.reject()).then(status=>{live=Boolean(status.live);$('connection-state').textContent=live?'本地已连接 · 上游 CLI 实时执行':'静态展示 · 真实记录可读';$('run-query').disabled=!live;}).catch(()=>{$('connection-state').textContent='静态展示 · 真实记录可读';$('run-query').textContent='实时查询需本地服务';$('query-caption').textContent+=' 启动项目 server.py 可进行实时查询。';});
fetch(base+'sources.json').then(r=>r.json()).then(files=>{for(const file of files){const a=document.createElement('a');a.textContent=file.file+' · '+file.lines+' 行';a.href=D.repository+'/blob/'+D.commit+'/fastapi/'+file.file;a.target='_blank';a.rel='noreferrer';$('source-list').append(a);}}).catch(()=>{$('source-list').textContent='文件清单加载失败，可直接下载下方 SHA-256 清单。';});
fetch(base+'integration.json').then(r=>r.json()).then(result=>{for(const key of ['mcp','incremental']){const ok=result[key]?.status==='passed';$(key+'-status').textContent=ok?'已验证':'未通过验证';$(key+'-status').classList.toggle('pending',!ok);}}).catch(()=>{for(const key of ['mcp','incremental'])$(key+'-status').textContent='记录未加载';});
})();
